import { useCallback, useEffect } from "react";
import {
  StreamingResponse,
  StreamingResponseContent,
  useTextStream,
} from "@/registry/erbium/blocks/streaming-response";
import type { StreamingResponseIslands } from "@/registry/erbium/blocks/streaming-response";
import { Button } from "@/registry/erbium/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/registry/erbium/ui/card";
import { simulateStream } from "../../streaming";

// Island data is model output, so each field is checked before it is shown.
const isText = (value: unknown): value is string =>
  // oxlint-disable-next-line anti-slop/no-runtime-typeof -- this is where model output is parsed.
  typeof value === "string";

// Defined outside the component, so the response is not formatted again on each render.
const islands: StreamingResponseIslands = {
  deployment: {
    pending: "Preparing the deployment…",
    // The data is model output: check it, and return null to show it as code instead.
    render: ({ id, service, version }) =>
      isText(service) && isText(version) ? (
        <Card key={id} size="sm" className="not-typeset my-4">
          <CardHeader>
            <CardTitle>Deploy {service}</CardTitle>
            <CardDescription>Version {version} is ready.</CardDescription>
          </CardHeader>
          <CardContent>
            <Button size="sm">Review changes</Button>
          </CardContent>
        </Card>
      ) : null,
  },
};

const reply = `The build passed. Confirm the deployment below.

\`\`\`island-deployment
{ "id": "api-1.4.0", "service": "api", "version": "1.4.0" }
\`\`\`

Nothing ships until you confirm it.
`;

export default function StreamingResponseCustomUiExample() {
  const { start, status, text } = useTextStream();

  const ask = useCallback(() => {
    void start((signal) => simulateStream(reply, { signal }));
  }, [start]);

  useEffect(() => {
    ask();
  }, [ask]);

  return (
    <div className="grid w-full max-w-md gap-group">
      <Button className="justify-self-start" variant="outline" size="sm" onClick={ask}>
        Replay
      </Button>
      <StreamingResponse text={text} status={status}>
        <StreamingResponseContent islands={islands} />
      </StreamingResponse>
    </div>
  );
}

/*
 * A stand-in for a model's reply, so streaming examples run without a server. In an app, pass
 * `useTextStream` the response body or the text stream of your model SDK.
 */

interface SimulatedStreamOptions {
  signal?: AbortSignal;
  /** Characters per chunk. */
  chunkSize?: number;
  /** Milliseconds between chunks. */
  interval?: number;
  /** How long the "model" thinks before the first chunk. */
  delay?: number;
}

const wait = async (milliseconds: number) => {
  // oxlint-disable-next-line promise/avoid-new -- a timer has no promise form in browsers.
  await new Promise((resolve) => {
    setTimeout(resolve, milliseconds);
  });
};

/**
 * Streams `text` a few characters at a time until it ends or `signal` aborts.
 *
 * @yields {string} The next chunk of `text`.
 */
const simulateStream = async function* simulateStream(
  text: string,
  { signal, chunkSize = 6, interval = 24, delay = 600 }: SimulatedStreamOptions = {},
) {
  await wait(delay);

  for (let start = 0; start < text.length; start += chunkSize) {
    if (signal?.aborted === true) {
      return;
    }

    yield text.slice(start, start + chunkSize);
    // Chunks arrive in order, one after another.
    // oxlint-disable-next-line no-await-in-loop
    await wait(interval);
  }
};

export { simulateStream };
